        const __m512 _t9_b = _mm512_unpackhi_ps(bB4, bC4);
        const __m512 _t10_b = _mm512_unpacklo_ps(bB5, bC5);
        const __m512 _t11_b = _mm512_unpackhi_ps(bB5, bC5);
        const __m512 _t12_b = _mm512_unpacklo_ps(bB6, bC6);
        const __m512 _t13_b = _mm512_unpackhi_ps(bB6, bC6);
        const __m512 _t14_b = _mm512_unpacklo_ps(bB7, bC7);
