        const __m512 bT4 = _mm512_shuffle_f32x4(_y1_b, _y9_b, 0x88);
        const __m512 bT5 = _mm512_shuffle_f32x4(_y3_b, _y11_b, 0x88);
        const __m512 bT6 = _mm512_shuffle_f32x4(_y5_b, _y13_b, 0x88);
        const __m512 bT7 = _mm512_shuffle_f32x4(_y7_b, _y15_b, 0x88);
        const __m512 bT8 = _mm512_shuffle_f32x4(_y0_b, _y8_b, 0xDD);
        const __m512 bT9 = _mm512_shuffle_f32x4(_y2_b, _y10_b, 0xDD);
