        _mm_prefetch((const char *)&zout[2*((size_t)0*OLs + k + 64)], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)0*OLs + k + 64) + 16], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)1*OLs + k + 64)], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)1*OLs + k + 64) + 16], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)2*OLs + k + 64)], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)2*OLs + k + 64) + 16], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)3*OLs + k + 64)], _MM_HINT_T0);
        _mm_prefetch((const char *)&zout[2*((size_t)3*OLs + k + 64) + 16], _MM_HINT_T0);
