        const __m512 lane_re_0 = _mm512_loadu_ps(&zin[2*(size_t)k]);
        const __m512 lane_im_0 = _mm512_loadu_ps(&zin[2*(size_t)k + 16]);
        const __m512 lane_re_1 = _mm512_loadu_ps(&zin[2*((size_t)1*Ls + k)]);
        const __m512 lane_im_1 = _mm512_loadu_ps(&zin[2*((size_t)1*Ls + k) + 16]);
        const __m512 lane_re_2 = _mm512_loadu_ps(&zin[2*((size_t)2*Ls + k)]);
        const __m512 lane_im_2 = _mm512_loadu_ps(&zin[2*((size_t)2*Ls + k) + 16]);
