        const __m512 aT4 = _mm512_shuffle_f32x4(_y1_a, _y9_a, 0x88);
        const __m512 aT5 = _mm512_shuffle_f32x4(_y3_a, _y11_a, 0x88);
        const __m512 aT6 = _mm512_shuffle_f32x4(_y5_a, _y13_a, 0x88);
        const __m512 aT7 = _mm512_shuffle_f32x4(_y7_a, _y15_a, 0x88);
        const __m512 aT8 = _mm512_shuffle_f32x4(_y0_a, _y8_a, 0xDD);
        const __m512 aT9 = _mm512_shuffle_f32x4(_y2_a, _y10_a, 0xDD);
        const __m512 aT10 = _mm512_shuffle_f32x4(_y4_a, _y12_a, 0xDD);
        const __m512 aT11 = _mm512_shuffle_f32x4(_y6_a, _y14_a, 0xDD);
        const __m512 aT12 = _mm512_shuffle_f32x4(_y1_a, _y9_a, 0xDD);
        const __m512 aT13 = _mm512_shuffle_f32x4(_y3_a, _y11_a, 0xDD);
        const __m512 aT14 = _mm512_shuffle_f32x4(_y5_a, _y13_a, 0xDD);
        const __m512 aT15 = _mm512_shuffle_f32x4(_y7_a, _y15_a, 0xDD);
        float * __restrict__ ap0 = zout + 32*rb[k+0];
        _mm512_storeu_ps(&ap0[0], aT0);
        _mm512_storeu_ps(&ap0[16], aT1);
        float * __restrict__ ap1 = zout + 32*rb[k+1];
        _mm512_storeu_ps(&ap1[0], aT2);
        _mm512_storeu_ps(&ap1[16], aT3);
        float * __restrict__ ap2 = zout + 32*rb[k+2];
        _mm512_storeu_ps(&ap2[0], aT4);
        _mm512_storeu_ps(&ap2[16], aT5);
        float * __restrict__ ap3 = zout + 32*rb[k+3];
        _mm512_storeu_ps(&ap3[0], aT6);
        _mm512_storeu_ps(&ap3[16], aT7);
        float * __restrict__ ap4 = zout + 32*rb[k+4];
        _mm512_storeu_ps(&ap4[0], aT8);
        _mm512_storeu_ps(&ap4[16], aT9);
        float * __restrict__ ap5 = zout + 32*rb[k+5];
        _mm512_storeu_ps(&ap5[0], aT10);
        _mm512_storeu_ps(&ap5[16], aT11);
        float * __restrict__ ap6 = zout + 32*rb[k+6];
        _mm512_storeu_ps(&ap6[0], aT12);
        _mm512_storeu_ps(&ap6[16], aT13);
        float * __restrict__ ap7 = zout + 32*rb[k+7];
        _mm512_storeu_ps(&ap7[0], aT14);
        _mm512_storeu_ps(&ap7[16], aT15);
        /* ---- half B: columns k+8..k+15 -> runs rb[k+8..k+15] (1 block pair each) ---- */
        const __m512 b0 = _mm512_loadu_ps(&zin[2*(size_t)k + 16]);
        const __m512 b1 = _mm512_loadu_ps(&zin[2*((size_t)1*Ls + k) + 16]);
        const __m512 b2 = _mm512_loadu_ps(&zin[2*((size_t)2*Ls + k) + 16]);
        const __m512 b3 = _mm512_loadu_ps(&zin[2*((size_t)3*Ls + k) + 16]);
        const __m512 b4 = _mm512_loadu_ps(&zin[2*((size_t)4*Ls + k) + 16]);
        const __m512 b5 = _mm512_loadu_ps(&zin[2*((size_t)5*Ls + k) + 16]);
        const __m512 b6 = _mm512_loadu_ps(&zin[2*((size_t)6*Ls + k) + 16]);
        const __m512 b7 = _mm512_loadu_ps(&zin[2*((size_t)7*Ls + k) + 16]);
        const __m512 b8 = _mm512_loadu_ps(&zin[2*((size_t)8*Ls + k) + 16]);
        const __m512 b9 = _mm512_loadu_ps(&zin[2*((size_t)9*Ls + k) + 16]);
        const __m512 b10 = _mm512_loadu_ps(&zin[2*((size_t)10*Ls + k) + 16]);
        const __m512 b11 = _mm512_loadu_ps(&zin[2*((size_t)11*Ls + k) + 16]);
        const __m512 b12 = _mm512_loadu_ps(&zin[2*((size_t)12*Ls + k) + 16]);
        const __m512 b13 = _mm512_loadu_ps(&zin[2*((size_t)13*Ls + k) + 16]);
        const __m512 b14 = _mm512_loadu_ps(&zin[2*((size_t)14*Ls + k) + 16]);
        const __m512 b15 = _mm512_loadu_ps(&zin[2*((size_t)15*Ls + k) + 16]);
        const __m512 bb0 = _mm512_add_ps(b0, b8);
        const __m512 bd0 = _mm512_sub_ps(b0, b8);
        const __m512 bb1 = _mm512_add_ps(b1, b9);
        const __m512 bd1 = _mm512_sub_ps(b1, b9);
        const __m512 bb2 = _mm512_add_ps(b2, b10);
        const __m512 bd2 = _mm512_sub_ps(b2, b10);
        const __m512 bb3 = _mm512_add_ps(b3, b11);
        const __m512 bd3 = _mm512_sub_ps(b3, b11);
        const __m512 bb4 = _mm512_add_ps(b4, b12);
        const __m512 bd4 = _mm512_sub_ps(b4, b12);
        const __m512 bb5 = _mm512_add_ps(b5, b13);
        const __m512 bd5 = _mm512_sub_ps(b5, b13);
        const __m512 bb6 = _mm512_add_ps(b6, b14);
        const __m512 bd6 = _mm512_sub_ps(b6, b14);
        const __m512 bb7 = _mm512_add_ps(b7, b15);
        const __m512 bd7 = _mm512_sub_ps(b7, b15);
        const __m512 bc1f = _mm512_permute_ps(bd1, 0xB1);
        const __m512 bc1 = _mm512_fmadd_ps(bc1f, _zs1, _mm512_mul_ps(bd1, _zc1));
        const __m512 bc2f = _mm512_permute_ps(bd2, 0xB1);
        const __m512 bc2 = _mm512_fmadd_ps(bc2f, _zs2, _mm512_mul_ps(bd2, _zc2));
        const __m512 bc3f = _mm512_permute_ps(bd3, 0xB1);
        const __m512 bc3 = _mm512_fmadd_ps(bc3f, _zs3, _mm512_mul_ps(bd3, _zc3));
        const __m512 bc5f = _mm512_permute_ps(bd5, 0xB1);
        const __m512 bc5 = _mm512_fmadd_ps(bc5f, _zs5, _mm512_mul_ps(bd5, _zc5));
        const __m512 bc6f = _mm512_permute_ps(bd6, 0xB1);
        const __m512 bc6 = _mm512_fmadd_ps(bc6f, _zs6, _mm512_mul_ps(bd6, _zc6));
        const __m512 bc7f = _mm512_permute_ps(bd7, 0xB1);
        const __m512 bc7 = _mm512_fmadd_ps(bc7f, _zs7, _mm512_mul_ps(bd7, _zc7));
        const __m512 bc4 = _mm512_permute_ps(bd4, 0xB1);
        const __m512 beb0 = _mm512_add_ps(bb0, bb4);
        const __m512 bed0 = _mm512_sub_ps(bb0, bb4);
        const __m512 beb1 = _mm512_add_ps(bb1, bb5);
        const __m512 bed1 = _mm512_sub_ps(bb1, bb5);
