        const __m512 bec1 = _mm512_fmadd_ps(bec1f, _zs2, _mm512_mul_ps(bed1, _zc2));
        const __m512 bec2 = _mm512_permute_ps(bed2, 0xB1);
        const __m512 bec3f = _mm512_permute_ps(bed3, 0xB1);
        const __m512 bec3 = _mm512_fmadd_ps(bec3f, _zs6, _mm512_mul_ps(bed3, _zc6));
        const __m512 bB0t0 = _mm512_add_ps(beb0, beb2);
        const __m512 bB0t1 = _mm512_sub_ps(beb0, beb2);
        const __m512 bB0t2 = _mm512_add_ps(beb1, beb3);
        const __m512 bB0t3 = _mm512_sub_ps(beb1, beb3);
        const __m512 bB0r = _mm512_permute_ps(bB0t3, 0xB1);
        const __m512 bB0 = _mm512_add_ps(bB0t0, bB0t2);
        const __m512 bB4 = _mm512_sub_ps(bB0t0, bB0t2);
        const __m512 bB2 = _mm512_fmadd_ps(bB0r, _zq, bB0t1);
        const __m512 bB6 = _mm512_fnmadd_ps(bB0r, _zq, bB0t1);
        const __m512 bB1t0 = _mm512_fmadd_ps(bec2, _zq, bed0);
        const __m512 bB1t1 = _mm512_fnmadd_ps(bec2, _zq, bed0);
        const __m512 bB1t2 = _mm512_add_ps(bec1, bec3);
        const __m512 bB1t3 = _mm512_sub_ps(bec1, bec3);
        const __m512 bB1r = _mm512_permute_ps(bB1t3, 0xB1);
        const __m512 bB1 = _mm512_add_ps(bB1t0, bB1t2);
        const __m512 bB5 = _mm512_sub_ps(bB1t0, bB1t2);
        const __m512 bB3 = _mm512_fmadd_ps(bB1r, _zq, bB1t1);
        const __m512 bB7 = _mm512_fnmadd_ps(bB1r, _zq, bB1t1);
        const __m512 bob0 = _mm512_fmadd_ps(bc4, _zq, bd0);
        const __m512 bod0 = _mm512_fnmadd_ps(bc4, _zq, bd0);
        const __m512 bob1 = _mm512_add_ps(bc1, bc5);
        const __m512 bod1 = _mm512_sub_ps(bc1, bc5);
        const __m512 bob2 = _mm512_add_ps(bc2, bc6);
        const __m512 bod2 = _mm512_sub_ps(bc2, bc6);
        const __m512 bob3 = _mm512_add_ps(bc3, bc7);
        const __m512 bod3 = _mm512_sub_ps(bc3, bc7);
        const __m512 boc1f = _mm512_permute_ps(bod1, 0xB1);
        const __m512 boc1 = _mm512_fmadd_ps(boc1f, _zs2, _mm512_mul_ps(bod1, _zc2));
        const __m512 boc2 = _mm512_permute_ps(bod2, 0xB1);
        const __m512 boc3f = _mm512_permute_ps(bod3, 0xB1);
        const __m512 boc3 = _mm512_fmadd_ps(boc3f, _zs6, _mm512_mul_ps(bod3, _zc6));
        const __m512 bC0t0 = _mm512_add_ps(bob0, bob2);
        const __m512 bC0t1 = _mm512_sub_ps(bob0, bob2);
        const __m512 bC0t2 = _mm512_add_ps(bob1, bob3);
        const __m512 bC0t3 = _mm512_sub_ps(bob1, bob3);
        const __m512 bC0r = _mm512_permute_ps(bC0t3, 0xB1);
        const __m512 bC0 = _mm512_add_ps(bC0t0, bC0t2);
        const __m512 bC4 = _mm512_sub_ps(bC0t0, bC0t2);
        const __m512 bC2 = _mm512_fmadd_ps(bC0r, _zq, bC0t1);
        const __m512 bC6 = _mm512_fnmadd_ps(bC0r, _zq, bC0t1);
        const __m512 bC1t0 = _mm512_fmadd_ps(boc2, _zq, bod0);
        const __m512 bC1t1 = _mm512_fnmadd_ps(boc2, _zq, bod0);
        const __m512 bC1t2 = _mm512_add_ps(boc1, boc3);
        const __m512 bC1t3 = _mm512_sub_ps(boc1, boc3);
        const __m512 bC1r = _mm512_permute_ps(bC1t3, 0xB1);
        const __m512 bC1 = _mm512_add_ps(bC1t0, bC1t2);
        const __m512 bC5 = _mm512_sub_ps(bC1t0, bC1t2);
        const __m512 bC3 = _mm512_fmadd_ps(bC1r, _zq, bC1t1);
        const __m512 bC7 = _mm512_fnmadd_ps(bC1r, _zq, bC1t1);
        const __m512 _t0_b = _mm512_unpacklo_ps(bB0, bC0);
        const __m512 _t1_b = _mm512_unpackhi_ps(bB0, bC0);
        const __m512 _t2_b = _mm512_unpacklo_ps(bB1, bC1);
        const __m512 _t3_b = _mm512_unpackhi_ps(bB1, bC1);
        const __m512 _t4_b = _mm512_unpacklo_ps(bB2, bC2);
        const __m512 _t5_b = _mm512_unpackhi_ps(bB2, bC2);
        const __m512 _t6_b = _mm512_unpacklo_ps(bB3, bC3);
        const __m512 _t7_b = _mm512_unpackhi_ps(bB3, bC3);
        const __m512 _t8_b = _mm512_unpacklo_ps(bB4, bC4);
        const __m512 _t9_b = _mm512_unpackhi_ps(bB4, bC4);
        const __m512 _t10_b = _mm512_unpacklo_ps(bB5, bC5);
        const __m512 _t11_b = _mm512_unpackhi_ps(bB5, bC5);
        const __m512 _t12_b = _mm512_unpacklo_ps(bB6, bC6);
        const __m512 _t13_b = _mm512_unpackhi_ps(bB6, bC6);
        const __m512 _t14_b = _mm512_unpacklo_ps(bB7, bC7);
        const __m512 _t15_b = _mm512_unpackhi_ps(bB7, bC7);
        const __m512 _x0_b = _mm512_shuffle_ps(_t0_b, _t2_b, 0x44);
        const __m512 _x1_b = _mm512_shuffle_ps(_t0_b, _t2_b, 0xEE);
        const __m512 _x2_b = _mm512_shuffle_ps(_t1_b, _t3_b, 0x44);
        const __m512 _x3_b = _mm512_shuffle_ps(_t1_b, _t3_b, 0xEE);
        const __m512 _x4_b = _mm512_shuffle_ps(_t4_b, _t6_b, 0x44);
        const __m512 _x5_b = _mm512_shuffle_ps(_t4_b, _t6_b, 0xEE);
        const __m512 _x6_b = _mm512_shuffle_ps(_t5_b, _t7_b, 0x44);
        const __m512 _x7_b = _mm512_shuffle_ps(_t5_b, _t7_b, 0xEE);
        const __m512 _x8_b = _mm512_shuffle_ps(_t8_b, _t10_b, 0x44);
        const __m512 _x9_b = _mm512_shuffle_ps(_t8_b, _t10_b, 0xEE);
        const __m512 _x10_b = _mm512_shuffle_ps(_t9_b, _t11_b, 0x44);
        const __m512 _x11_b = _mm512_shuffle_ps(_t9_b, _t11_b, 0xEE);
        const __m512 _x12_b = _mm512_shuffle_ps(_t12_b, _t14_b, 0x44);
        const __m512 _x13_b = _mm512_shuffle_ps(_t12_b, _t14_b, 0xEE);
        const __m512 _x14_b = _mm512_shuffle_ps(_t13_b, _t15_b, 0x44);
        const __m512 _x15_b = _mm512_shuffle_ps(_t13_b, _t15_b, 0xEE);
        const __m512 _y0_b = _mm512_shuffle_f32x4(_x0_b, _x4_b, 0x88);
        const __m512 _y1_b = _mm512_shuffle_f32x4(_x0_b, _x4_b, 0xDD);
        const __m512 _y2_b = _mm512_shuffle_f32x4(_x1_b, _x5_b, 0x88);
        const __m512 _y3_b = _mm512_shuffle_f32x4(_x1_b, _x5_b, 0xDD);
        const __m512 _y4_b = _mm512_shuffle_f32x4(_x2_b, _x6_b, 0x88);
        const __m512 _y5_b = _mm512_shuffle_f32x4(_x2_b, _x6_b, 0xDD);
        const __m512 _y6_b = _mm512_shuffle_f32x4(_x3_b, _x7_b, 0x88);
        const __m512 _y7_b = _mm512_shuffle_f32x4(_x3_b, _x7_b, 0xDD);
        const __m512 _y8_b = _mm512_shuffle_f32x4(_x8_b, _x12_b, 0x88);
        const __m512 _y9_b = _mm512_shuffle_f32x4(_x8_b, _x12_b, 0xDD);
        const __m512 _y10_b = _mm512_shuffle_f32x4(_x9_b, _x13_b, 0x88);
        const __m512 _y11_b = _mm512_shuffle_f32x4(_x9_b, _x13_b, 0xDD);
        const __m512 _y12_b = _mm512_shuffle_f32x4(_x10_b, _x14_b, 0x88);
        const __m512 _y13_b = _mm512_shuffle_f32x4(_x10_b, _x14_b, 0xDD);
        const __m512 _y14_b = _mm512_shuffle_f32x4(_x11_b, _x15_b, 0x88);
        const __m512 _y15_b = _mm512_shuffle_f32x4(_x11_b, _x15_b, 0xDD);
        const __m512 bT0 = _mm512_shuffle_f32x4(_y0_b, _y8_b, 0x88);
        const __m512 bT1 = _mm512_shuffle_f32x4(_y2_b, _y10_b, 0x88);
        const __m512 bT2 = _mm512_shuffle_f32x4(_y4_b, _y12_b, 0x88);
        const __m512 bT3 = _mm512_shuffle_f32x4(_y6_b, _y14_b, 0x88);
        const __m512 bT4 = _mm512_shuffle_f32x4(_y1_b, _y9_b, 0x88);
        const __m512 bT5 = _mm512_shuffle_f32x4(_y3_b, _y11_b, 0x88);
        const __m512 bT6 = _mm512_shuffle_f32x4(_y5_b, _y13_b, 0x88);
        const __m512 bT7 = _mm512_shuffle_f32x4(_y7_b, _y15_b, 0x88);
        const __m512 bT8 = _mm512_shuffle_f32x4(_y0_b, _y8_b, 0xDD);
        const __m512 bT9 = _mm512_shuffle_f32x4(_y2_b, _y10_b, 0xDD);
        const __m512 bT10 = _mm512_shuffle_f32x4(_y4_b, _y12_b, 0xDD);
        const __m512 bT11 = _mm512_shuffle_f32x4(_y6_b, _y14_b, 0xDD);
        const __m512 bT12 = _mm512_shuffle_f32x4(_y1_b, _y9_b, 0xDD);
        const __m512 bT13 = _mm512_shuffle_f32x4(_y3_b, _y11_b, 0xDD);
        const __m512 bT14 = _mm512_shuffle_f32x4(_y5_b, _y13_b, 0xDD);
        const __m512 bT15 = _mm512_shuffle_f32x4(_y7_b, _y15_b, 0xDD);
        float * __restrict__ bp0 = zout + 32*rb[k+8];
        _mm512_storeu_ps(&bp0[0], bT0);
        _mm512_storeu_ps(&bp0[16], bT1);
        float * __restrict__ bp1 = zout + 32*rb[k+9];
        _mm512_storeu_ps(&bp1[0], bT2);
        _mm512_storeu_ps(&bp1[16], bT3);
        float * __restrict__ bp2 = zout + 32*rb[k+10];
        _mm512_storeu_ps(&bp2[0], bT4);
        _mm512_storeu_ps(&bp2[16], bT5);
        float * __restrict__ bp3 = zout + 32*rb[k+11];
        _mm512_storeu_ps(&bp3[0], bT6);
        _mm512_storeu_ps(&bp3[16], bT7);
        float * __restrict__ bp4 = zout + 32*rb[k+12];
        _mm512_storeu_ps(&bp4[0], bT8);
        _mm512_storeu_ps(&bp4[16], bT9);
        float * __restrict__ bp5 = zout + 32*rb[k+13];
        _mm512_storeu_ps(&bp5[0], bT10);
        _mm512_storeu_ps(&bp5[16], bT11);
        float * __restrict__ bp6 = zout + 32*rb[k+14];
        _mm512_storeu_ps(&bp6[0], bT12);
        _mm512_storeu_ps(&bp6[16], bT13);
        float * __restrict__ bp7 = zout + 32*rb[k+15];
        _mm512_storeu_ps(&bp7[0], bT14);
        _mm512_storeu_ps(&bp7[16], bT15);
