        const __m512 t3 = _mm512_loadu_ps(&tw_re[6*(size_t)k + 80]);
        const __m512 t4 = _mm512_fnmadd_ps(t2, t3, _mm512_mul_ps(t0, t1));
        const __m512 t5 = _mm512_fmadd_ps(t0, t3, _mm512_mul_ps(t2, t1));
        const __m512 t9 = lane_re_1;
        const __m512 t10 = _mm512_loadu_ps(&tw_re[6*(size_t)k + 0]);
        const __m512 t11 = lane_im_1;
        const __m512 t12 = _mm512_loadu_ps(&tw_re[6*(size_t)k + 16]);
        const __m512 t13 = _mm512_fnmadd_ps(t11, t12, _mm512_mul_ps(t9, t10));
        const __m512 t14 = _mm512_fmadd_ps(t9, t12, _mm512_mul_ps(t11, t10));
        const __m512 t16 = _mm512_sub_ps(t14, t5);
        const __m512 t18 = _mm512_sub_ps(t13, t4);
        const __m512 t35 = _mm512_add_ps(t5, t14);
        const __m512 t36 = _mm512_add_ps(t4, t13);
        const __m512 t20 = lane_re_2;
        const __m512 t21 = _mm512_loadu_ps(&tw_re[6*(size_t)k + 32]);
        const __m512 t22 = lane_im_2;
