        _mm512_storeu_ps(&zout[2*((size_t)1*OLs + k) + 16], _mm512_permutex2var_ps(_pr_1, _zs_po, _qi_1));
        const __m512 _pr_2 = t40;
        const __m512 _qi_2 = t42;
        _mm512_storeu_ps(&zout[2*((size_t)2*OLs + k)], _mm512_permutex2var_ps(_pr_2, _zs_pe, _qi_2));
        _mm512_storeu_ps(&zout[2*((size_t)2*OLs + k) + 16], _mm512_permutex2var_ps(_pr_2, _zs_po, _qi_2));
        const __m512 _pr_3 = t32;
